// Intended function: progress Praetor combat phases and emit learnable, deterministic boss actions instead of opaque instant damage.
#include "combat/PraetorBoss.hpp"
#include "core/Determinism.hpp"
#include <algorithm>
namespace elysium{
void PraetorBossPlanner::applyDamage(PraetorState&s,float sd,float hd){s.shield=std::max(0.f,s.shield-sd);if(s.shield<=0)s.health=std::max(0.f,s.health-hd);if(s.health<=0)s.phase=PraetorPhase::Defeated;else if(s.health<.25f)s.phase=PraetorPhase::FinalStand;else if(s.health<.55f)s.phase=PraetorPhase::Overload;else if(s.shield<=0)s.phase=PraetorPhase::Assault;else if(s.phase==PraetorPhase::Arrival)s.phase=PraetorPhase::Shielded;}
std::vector<PraetorIntent> PraetorBossPlanner::update(PraetorState&s,std::uint64_t tick,std::uint64_t target){std::vector<PraetorIntent>o;if(s.phase==PraetorPhase::Defeated)return o;if(tick<s.nextAbilityTick)return o;auto r=mix64(s.stableId^mix64(tick/30)^s.sequence++);PraetorAbility a=PraetorAbility::LanceSweep;switch(s.phase){case PraetorPhase::Arrival:a=PraetorAbility::AegisPulse;s.phase=PraetorPhase::Shielded;break;case PraetorPhase::Shielded:a=(r&1)?PraetorAbility::DroneCall:PraetorAbility::LanceSweep;break;case PraetorPhase::Assault:a=(r%3==0)?PraetorAbility::GravityWell:(r%3==1?PraetorAbility::RiftStep:PraetorAbility::LanceSweep);break;case PraetorPhase::Overload:a=(r&1)?PraetorAbility::OverloadNova:PraetorAbility::ExecutionArc;break;case PraetorPhase::FinalStand:a=(r%3==0)?PraetorAbility::DroneCall:(r%3==1?PraetorAbility::ExecutionArc:PraetorAbility::OverloadNova);break;case PraetorPhase::Defeated:return o;}std::uint32_t tele=(a==PraetorAbility::OverloadNova?90u:(a==PraetorAbility::ExecutionArc?55u:35u));float mag=(s.phase==PraetorPhase::FinalStand?1.5f:1.f);o.push_back({mix64(s.stableId^s.sequence),s.stableId,target,a,tele,a==PraetorAbility::GravityWell?12.f:7.f,mag,a==PraetorAbility::DroneCall});s.lastAbilityTick=tick;s.nextAbilityTick=tick+tele+45u;return o;}
}
